/**
 * api/client.ts
 * The app's single HTTP client, built on openapi-fetch and typed from
 * api/schema.d.ts (generated by `npm run gen:api`).
 *
 * Every request passes through the middleware below, which:
 *  - attaches the bearer token from the auth store
 *  - logs failures and throws an ApiError for any non-2xx response
 *  - ends the session when an authenticated request returns 401
 * Because failures throw, callers never branch on an `error` field: call the
 * client from a resource hook and read errors from TanStack Query state.
 *
 * Usage (inside a resource hook):
 *   unwrap(client.GET("/v1/items/{item}", { params: { path: { item: 1 } } }))
 *
 * Environment:
 *   EXPO_PUBLIC_IS_TESTING=true  -> EXPO_PUBLIC_API_DEV_URL  (mock / staging)
 *   EXPO_PUBLIC_IS_TESTING=false -> EXPO_PUBLIC_API_BASE_URL (production)
 *
 * When you add a production auth store (stores/prod/auth.store.ts), update
 * the useAuthStore import below.
 */
import { useAuthStore } from "@/stores/dev/auth.store";
import createClient, { type Middleware } from "openapi-fetch";
import { ApiError, type ErrorBody } from "./errors";
import type { paths } from "./schema";

const isTesting = process.env.EXPO_PUBLIC_IS_TESTING === "true";
const baseUrl = isTesting
  ? process.env.EXPO_PUBLIC_API_DEV_URL
  : process.env.EXPO_PUBLIC_API_BASE_URL;

if (!baseUrl) {
  throw new Error("API base URL is missing — check your .env");
}
if (__DEV__) {
  console.log(`[API] ${isTesting ? "TEST" : "PROD"} base URL: ${baseUrl}`);
}

const middleware: Middleware = {
  onRequest({ request }) {
    const token = useAuthStore.getState().token;
    if (token) request.headers.set("Authorization", `Bearer ${token}`);
    return request;
  },

  async onResponse({ request, response }) {
    if (response.ok) return;

    const body = (await response
      .clone()
      .json()
      .catch(() => null)) as ErrorBody | null;
    const method = request.method.toUpperCase();
    const path = new URL(request.url).pathname;

    console.error(`[API ERROR] ${method} ${path} | ${response.status}`, body);

    // A 401 only ends the session if the request carried a token, so a
    // wrong-password login is not mistaken for an expired session.
    if (response.status === 401 && request.headers.has("Authorization")) {
      void useAuthStore.getState().clearSession();
    }

    throw new ApiError(response.status, body, method, path);
  },

  onError({ error, request }) {
    // fetch itself threw (network failure or abort): log and let it propagate.
    console.error(
      `[API NETWORK ERROR] ${request.method} ${request.url}`,
      error,
    );
  },
};

export const client = createClient<paths>({
  baseUrl,
  headers: { Accept: "application/json" },
});
client.use(middleware);

/**
 * Resolves with the `data` field of a successful response, removing the
 * `{ message, data }` envelope so components never see it. Failures have
 * already thrown in the middleware, so `data` is always present here.
 *
 *   unwrap(client.GET("/v1/me"))  // -> the user object
 */
export async function unwrap<T>(
  request: Promise<{ data?: { data: T } }>,
): Promise<T> {
  const { data } = await request;
  return (data as { data: T }).data;
}

/**
 * For endpoints that return no payload (logout, change password...):
 * resolves with the server's `message`, ready to show in a toast.
 */
export async function unwrapMessage(
  request: Promise<{ data?: { message?: string | null } }>,
): Promise<string> {
  const { data } = await request;
  return data?.message ?? "";
}

/**
 * Builds a multipart/form-data request for file uploads. The generated type
 * for a file field is `string`, which a React Native file object is not, so
 * the typed body is bypassed and the FormData is assembled here.
 *
 *   client.POST("/v1/me/avatar", multipart({ avatar: file }))
 */
export type RNFile = { uri: string; name: string; type: string };

export function multipart(
  fields: Record<string, RNFile | string | number | boolean | null | undefined>,
) {
  return {
    body: {} as never,
    bodySerializer: () => {
      const form = new FormData();
      for (const [key, value] of Object.entries(fields)) {
        if (value == null) continue;
        // React Native's FormData accepts { uri, name, type } as a file part.
        form.append(
          key,
          typeof value === "object" ? (value as any) : String(value),
        );
      }
      return form;
    },
  };
}
